from pathlib import Path
import re,json,zlib,base64

BLOCK=zlib.decompress(base64.b64decode('')).decode()
AUDIT=zlib.decompress(base64.b64decode('')).decode()

p=Path("index.html")
s=p.read_text()
assert "FE QUEST PWA v127" in s
assert "const APP_VERSION = 'v127';" in s
assert "v128: Subject A 710-question quality audit / pass 1" not in s

s=s.replace("<title>FE QUEST PWA v127</title>","<title>FE QUEST PWA v128</title>",1)
s=s.replace("const APP_VERSION = 'v127';","const APP_VERSION = 'v128';",1)
s=s.replace("assert(PROFILE_SCHEMA_VERSION===5&&APP_VERSION==='v127','v127 version/schema contract drift');","assert(PROFILE_SCHEMA_VERSION===5&&APP_VERSION==='v128','v128 version/schema contract drift');",1)

marker="QUESTION_BANK.push(...CORE_A_CHALLENGE_QUESTIONS);\n"
assert marker in s
s=s.replace(marker, marker+"\n"+BLOCK+"\n", 1)

assert_marker="    assert([...CORE_A_REFERENCE_PRACTICE_ANCHORS].every(id=>QUESTION_BANK.some(q=>q.coreTopicId===id&&isCoreTopicImmediatePracticeQuestion(q)&&['application','scenario','calculation','interpretation','trace'].includes(q.angle))),'v127 reference anchors need a concrete applied question');\n"
assert assert_marker in s
extra="""    assert(SUBJECT_A_V128_QUALITY_OVERRIDE_IDS.length===28,'v128 full-bank pass1 override count drift');
    assert(SUBJECT_A_V128_QUALITY_OVERRIDE_IDS.every(id=>QUESTION_BANK.some(q=>q.id===id&&q.qualityAudit==='v128-full-bank-pass1')),'v128 quality overrides must be applied');
    assert(SUBJECT_A_V128_NORMALIZED_STEMS>=60,'v128 generic stem normalization unexpectedly low');
    assert(!QUESTION_BANK.some(q=>/目的・特徴が同じ|区別する必要はない/.test([q.q,...q.options].join(' '))),'v128 obvious same/no-distinction distractor cue remains');
"""
s=s.replace(assert_marker,assert_marker+extra,1)
p.write_text(s)

m=Path("manifest.webmanifest")
obj=json.loads(m.read_text())
assert obj["name"]=="FE QUEST v127"
obj["name"]="FE QUEST v128"
obj["description"]="基本情報技術者試験向けPWA。v128では科目A710問を全件横断監査し、反復的なメタ問題文を整理するとともに、明白な誤答キューや選択肢品質の弱かった28問を具体的な状況・計算・判断問題へ改善。問題数・正答位置・認知レベル総数・Profile Schema v5は維持。"
m.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+"\n")

sw=Path("sw.js")
w=sw.read_text()
assert "const APP_VERSION = 'v127';" in w
w=w.replace("const APP_VERSION = 'v127';","const APP_VERSION = 'v128';",1)
w=w.replace("const CACHE_NAME = 'fe-quest-v127-1';","const CACHE_NAME = 'fe-quest-v128-1';",1)
sw.write_text(w)

Path("audits/SUBJECT_A_710_QUESTION_QUALITY_AUDIT_v128.txt").write_text(AUDIT)
print("APPLY_V128_OK")
